let todos  = JSON.parse(sessionStorage.getItem('todos') || '[]');
let filter = 'all'; // 'all' | 'active' | 'done'

const save  = () => sessionStorage.setItem('todos', JSON.stringify(todos));
const add   = text  => { todos.push({ id: Date.now(), text, done: false }); save(); render(); };
const toggle = id  => { todos = todos.map(t => t.id === id ? { ...t, done: !t.done } : t); save(); render(); };
const remove = id  => { todos = todos.filter(t => t.id !== id); save(); render(); };

// --- Render ---
function render() {
  const list    = document.getElementById('todo-list');
  const counter = document.getElementById('counter');
  const visible = todos.filter(t =>
    filter === 'all'    ? true :
    filter === 'active' ? !t.done :
    t.done
  );

  list.innerHTML = visible.map(t => `
    <li class="todo-item ${t.done ? 'done' : ''}" data-id="${t.id}">
      <span class="todo-text">${t.text}</span>
      <button class="btn-delete" data-action="delete">×</button>
    </li>
  `).join('');

  counter.textContent = `${todos.filter(t => !t.done).length} tâche(s) restante(s)`;

  // Filtres actifs
  document.querySelectorAll('.filter-btn').forEach(btn =>
    btn.classList.toggle('active', btn.dataset.filter === filter)
  );
}

