function createCounter(initialValue = 0, step = 1) {
  // Variables privées — accessibles uniquement via les closures
  let count   = initialValue;
  const history = [initialValue]; // pile pour undo
  let historyIndex = 0;

  const pushHistory = (value) => {
    // Effacer l'historique "futur" si on agit après un undo
    history.splice(historyIndex + 1);
    history.push(value);
    historyIndex = history.length - 1;
  };

  return {
    increment() {
      count += step;
      pushHistory(count);
    },
    decrement() {
      count -= step;
      pushHistory(count);
    },
    reset() {
      count = initialValue;
      pushHistory(count);
    },
    getValue() {
      return count;
    },
    undo() {
      if (historyIndex > 0) {
        historyIndex--;
        count = history[historyIndex];
      }
    },
    redo() {
      if (historyIndex < history.length - 1) {
        historyIndex++;
        count = history[historyIndex];
      }
    },
    getHistory() {
      return [...history]; // copie pour préserver l'immutabilité
    }
  };
}

