// ── Type Guard ──
function isApiError<T>(response: ApiResponse<T>): response is ApiResponse<never> {
  return response.status >= 400 || typeof response.error === 'string';
}

// ── Fonction générique ──
async function fetchResource<T>(url: string): Promise<ApiResponse<T>> {
  try {
    const res = await fetch(url);
    const data: T = await res.json() as T;
    return { data: Object.freeze(data), status: res.status };
  } catch (err: unknown) {
    const message = err instanceof Error ? err.message : 'Erreur inconnue';
    return { data: undefined as never, status: 0, error: message };
  }
}

