import { useReducer, useMemo } from 'react';

// ── Types d'action ──
const ADD_ITEM    = 'ADD_ITEM';
const REMOVE_ITEM = 'REMOVE_ITEM';
const UPDATE_QTY  = 'UPDATE_QTY';
const CLEAR_CART  = 'CLEAR_CART';

// ── Reducer pur ──
function cartReducer(state, action) {
  switch (action.type) {
    case ADD_ITEM: {
      const exists = state.find(item => item.id === action.payload.id);
      if (exists) {
        return state.map(item =>
          item.id === action.payload.id
            ? { ...item, quantity: item.quantity + 1 }
            : item
        );
      }
      return [...state, { ...action.payload, quantity: 1 }];
    }
    case REMOVE_ITEM:
      return state.filter(item => item.id !== action.payload.id);

    case UPDATE_QTY:
      return state.map(item =>
        item.id === action.payload.id
          ? { ...item, quantity: Math.max(1, action.payload.quantity) }
          : item
      );
    case CLEAR_CART:
      return [];

    default:
      return state;
  }
}

// ── Composant enfant CartItem ──
function CartItem({ item, dispatch }) {
  return (
    <li className="cart-item">
      <span>{item.name}</span>
      <input
        type="number"
        min="1"
        value={item.quantity}
        onChange={e => dispatch({
          type: UPDATE_QTY,
          payload: { id: item.id, quantity: Number(e.target.value) }
        })}
      />
      <span>{(item.price * item.quantity).toFixed(2)} €</span>
      <button onClick={() => dispatch({ type: REMOVE_ITEM, payload: { id: item.id } })}>
        ×
      </button>
    </li>
  );
}

// ── Composant principal ShoppingCart ──
export default function ShoppingCart() {
  const [cart, dispatch] = useReducer(cartReducer, []);

  const total = useMemo(
    () => cart.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cart]  // recalcul uniquement si cart change
  );

  // Produits disponibles (normalement fetchés)
  const products = [
    { id: 1, name: 'Clavier mécanique', price: 129.99 },
    { id: 2, name: 'Souris ergonomique', price: 79.50 },
    { id: 3, name: 'Webcam 4K',          price: 199.00 },
  ];

  return (
    <div className="cart">
      <h2>Produits disponibles</h2>
      {products.map(p => (
        <button key={p.id} onClick={() => dispatch({ type: ADD_ITEM, payload: p })}>
          + {p.name} ({p.price} €)
        </button>
      ))}

      <h2>Panier ({cart.length} article{cart.length > 1 ? 's' : ''})</h2>
      <ul>
        {cart.map(item => <CartItem key={item.id} item={item} dispatch={dispatch} />)}
      </ul>

      <p><strong>Total : {total.toFixed(2)} €</strong></p>
      <button onClick={() => dispatch({ type: CLEAR_CART })}>Vider le panier</button>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';

// Cache partagé entre toutes les instances du hook
const fetchCache = new Map();

export function useFetch(url, options = {}) {
  const { skip = false } = options;

  const [state, setState] = useState({
    data    : null,
    loading : !skip,
    error   : null,
  });

  // Compteur pour forcer le re-fetch (invalidation cache)
  const [refreshKey, setRefreshKey] = useState(0);
  const isMountedRef = useRef(true);

  useEffect(() => {
    isMountedRef.current = true;
    return () => { isMountedRef.current = false; };
  }, []);

  useEffect(() => {
    if (!url || skip) return;

    // Cache hit (sauf si refresh demandé)
    if (fetchCache.has(url) && refreshKey === 0) {
      setState({ data: fetchCache.get(url), loading: false, error: null });
      return;
    }

    const controller = new AbortController();
    setState(prev => ({ ...prev, loading: true, error: null }));

    (async () => {
      try {
        const res = await fetch(url, { signal: controller.signal });
        if (!res.ok) throw new Error(`HTTP ${res.status}`);
        const data = await res.json();

        fetchCache.set(url, data); // Mise en cache

        if (isMountedRef.current) {
          setState({ data, loading: false, error: null });
        }
      } catch (err) {
        // AbortError = annulation volontaire, pas une vraie erreur
        if (err.name === 'AbortError') return;
        if (isMountedRef.current) {
          setState({ data: null, loading: false, error: err.message });
        }
      }
    })();

    // Cleanup : annule la requête si url change ou composant démonté
    return () => controller.abort();
  }, [url, skip, refreshKey]);

  const refetch = useCallback(() => {
    fetchCache.delete(url); // Invalide le cache
    setRefreshKey(k => k + 1); // Force la ré-exécution du useEffect
  }, [url]);

  return { ...state, refetch };
}

// ── Utilisation ──
function UserProfile({ userId }) {
  const { data, loading, error, refetch } = useFetch(
    `/api/users/${userId}`
  );

  if (loading) return <p>Chargement…</p>;
  if (error)   return <p>Erreur : {error} <button onClick={refetch}>Réessayer</button></p>;
  return <div><h2>{data?.name}</h2><button onClick={refetch}>↻</button></div>;
}

