// ── Données en mémoire ──
let articles = [];
let nextId   = 1;

// ── Middleware : Authentification ──
function requireAuth(req, res, next) {
  const auth  = req.headers['authorization'] || '';
  const token = auth.startsWith('Bearer ') ? auth.slice(7) : '';
  if (token !== 'james-secret-2024') {
    const err  = new Error('Token manquant ou invalide');
    err.status = 401;
    return next(err);
  }
  next();
}

// ── Middleware : Validation du body ──
function validateArticle(req, res, next) {
  const { titre, contenu } = req.body;
  const errors = [];
  if (!titre   || titre.trim().length < 3)   errors.push('titre : 3 caractères minimum');
  if (!contenu || contenu.trim().length < 10) errors.push('contenu : 10 caractères minimum');
  if (errors.length) {
    const err  = new Error('Validation échouée : ' + errors.join(', '));
    err.status = 422;
    err.errors = errors;
    return next(err);
  }
  next();
}

// ── Routes ──
const router = express.Router();

// GET /api/articles
router.get('/', (req, res) => {
  res.json({ success: true, data: articles, count: articles.length });
});

// GET /api/articles/:id
router.get('/:id', (req, res, next) => {
  const article = articles.find(a => a.id === Number(req.params.id));
  if (!article) {
    const err = new Error(`Article #${req.params.id} introuvable`);
    err.status = 404;
    return next(err);
  }
  res.json({ success: true, data: article });
});

// POST /api/articles  (auth + validation)
router.post('/', requireAuth, validateArticle, (req, res) => {
  const article = {
    id      : nextId++,
    titre   : req.body.titre.trim(),
    contenu : req.body.contenu.trim(),
    createdAt: new Date().toISOString(),
  };
  articles.push(article);
  res.status(201).json({ success: true, data: article });
});

// PUT /api/articles/:id  (auth + validation)
router.put('/:id', requireAuth, validateArticle, (req, res, next) => {
  const idx = articles.findIndex(a => a.id === Number(req.params.id));
  if (idx === -1) {
    const err = new Error('Article introuvable'); err.status = 404; return next(err);
  }
  articles[idx] = { ...articles[idx], ...req.body, id: articles[idx].id };
  res.json({ success: true, data: articles[idx] });
});

// DELETE /api/articles/:id  (auth)
router.delete('/:id', requireAuth, (req, res, next) => {
  const idx = articles.findIndex(a => a.id === Number(req.params.id));
  if (idx === -1) {
    const err = new Error('Article introuvable'); err.status = 404; return next(err);
  }
  articles.splice(idx, 1);
  res.status(204).send();
});

app.use('/api/articles', router);

