CREATE PROCEDURE placeOrder(
  IN  p_customer_id INT,
  IN  p_product_id  INT,
  IN  p_quantity    INT,
  OUT p_order_id    INT,
  OUT p_error       VARCHAR(255)
)
BEGIN
  DECLARE v_stock      INT DEFAULT 0;
  DECLARE v_price      DECIMAL(10,2) DEFAULT 0;
  DECLARE v_total      DECIMAL(10,2) DEFAULT 0;
  DECLARE EXIT HANDLER FOR SQLEXCEPTION
  BEGIN
    ROLLBACK;
    SET p_order_id = -1;
    SET p_error    = 'Erreur SQL inattendue — transaction annulée';
  END;

  START TRANSACTION;

  -- Verrou pessimiste : bloque la ligne jusqu'au COMMIT
  -- Empêche une autre transaction de lire et modifier le même stock
  SELECT stock, price
    INTO v_stock, v_price
    FROM products
   WHERE id = p_product_id
     FOR UPDATE;  -- <-- CRUCIAL pour la concurrence

  -- Vérification du stock
  IF v_stock < p_quantity THEN
    ROLLBACK;
    SET p_order_id = -1;
    SET p_error    = CONCAT('Stock insuffisant : disponible=', v_stock,
                            ', demandé=', p_quantity);
    LEAVE TRANSACTION_BLOCK;  -- sortie propre
  END IF;

  -- Décrément du stock
  UPDATE products
     SET stock = stock - p_quantity
   WHERE id = p_product_id;

  -- Calcul du total
  SET v_total = v_price * p_quantity;

  -- Insertion de la commande
  INSERT INTO orders (customer_id, total, status, created_at)
  VALUES (p_customer_id, v_total, 'pending', NOW());

  SET p_order_id = LAST_INSERT_ID();

  -- Insertion de la ligne de commande
  INSERT INTO order_items (order_id, product_id, quantity, unit_price)
  VALUES (p_order_id, p_product_id, p_quantity, v_price);

  COMMIT;
  SET p_error = NULL;
END //

