import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Observable, of, throwError } from 'rxjs';
import { catchError, map, shareReplay, tap } from 'rxjs/operators';

export interface Product {
  id: number; name: string; price: number; category: string;
}

@Injectable({ providedIn: 'root' })
export class ProductService {
  private readonly http = inject(HttpClient);
  private readonly cache = new Map<number, Product>(); // Cache en mémoire
  private readonly apiUrl = '/api/products';

  // Recherche avec résultats partagés (shareReplay)
  searchProducts(term: string): Observable<Product[]> {
    if (!term.trim()) return of([]);
    return this.http.get<Product[]>(`${this.apiUrl}?q=${encodeURIComponent(term)}`).pipe(
      map(products => products.slice(0, 20)), // Limite affichage
      catchError(this.handleError),
    );
  }

  getProduct(id: number): Observable<Product> {
    // Cache hit : retourne un Observable synchrone
    if (this.cache.has(id)) {
      return of(this.cache.get(id)!);
    }
    return this.http.get<Product>(`${this.apiUrl}/${id}`).pipe(
      tap(product => this.cache.set(id, product)), // Mise en cache à la réception
      shareReplay(1),                              // Partage entre plusieurs subscribers
      catchError(this.handleError),
    );
  }

  private handleError(error: HttpErrorResponse): Observable<never> {
    const message = error.status === 0
      ? 'Erreur réseau — serveur inaccessible'
      : `Erreur ${error.status} : ${error.message}`;
    console.error('[ProductService]', message);
    return throwError(() => new Error(message));
  }
}


