import { Component, inject, OnInit } from '@angular/core';
import { FormControl, ReactiveFormsModule } from '@angular/forms';
import { AsyncPipe, CommonModule } from '@angular/common';
import { Observable, EMPTY } from 'rxjs';
import { debounceTime, distinctUntilChanged, switchMap, catchError } from 'rxjs/operators';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ProductService, Product } from './product.service';

@Component({
  selector: 'app-product-list',
  standalone: true,
  imports: [ReactiveFormsModule, AsyncPipe, CommonModule],
  template: `
    <input
      [formControl]="searchControl"
      placeholder="Rechercher un produit…"
    />

    <p *ngIf="isSearching">🔍 Recherche en cours…</p>

    <!-- Le pipe async subscribe/unsubscribe automatiquement -->
    <ul *ngIf="products$ | async as products">
      <li *ngFor="let product of products; trackBy: trackById">
        {{ product.name }} — {{ product.price | currency:'EUR' }}
      </li>
      <li *ngIf="products.length === 0">Aucun résultat.</li>
    </ul>
  `,
})
export class ProductListComponent {
  private readonly productService = inject(ProductService);

  readonly searchControl = new FormControl('', { nonNullable: true });
  products$!: Observable<Product[]>;
  isSearching = false;

  constructor() {
    this.products$ = this.searchControl.valueChanges.pipe(
      debounceTime(300),          // Attend 300ms sans frappe
      distinctUntilChanged(),     // N'émet pas si la valeur n'a pas changé
      switchMap(term => {         // Annule la requête précédente si new frappe
        this.isSearching = true;
        return this.productService.searchProducts(term).pipe(
          tap(() => this.isSearching = false),
          catchError(() => { this.isSearching = false; return EMPTY; })
        );
      }),
      takeUntilDestroyed(),       // Se désabonne automatiquement au destroy du composant
    );
  }

  trackById(_: number, product: Product): number {
    return product.id;
  }
}

