  opacity: 1;
  animation: spin 0.7s linear infinite;
}
@keyframes spin { to { transform: rotate(360deg); } }


/* ════ 2. CARTE 3D AU HOVER ════ */
.card-3d-wrapper {
  perspective: 800px;    /* Plus bas = effet 3D plus prononcé */
}

.card-3d {
  transform-style: preserve-3d;
  transition: transform 0.4s ease-out, box-shadow 0.4s ease-out;
  will-change: transform; /* Prépare le layer GPU à l'avance */
  border-radius: 12px;
  background: #1f2937;
  padding: 24px;
}

.card-3d:hover {
  transform: rotateY(-8deg) rotateX(4deg) translateZ(20px);
  box-shadow: 16px 16px 40px rgba(0,0,0,0.4);
}

/* Reflet en pseudo-élément */
.card-3d::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(135deg, rgba(255,255,255,0.05) 0%, transparent 60%);
  border-radius: inherit;
  opacity: 0;
  transition: opacity 0.4s;
}
.card-3d:hover::before { opacity: 1; }


/* ════ 3. NOTIFICATION ANIMÉE ════ */
.notification {
  position: fixed;
  top: 16px; right: 16px;
  background: #1f2937;
  border: 1px solid #374151;
  border-left: 3px solid #3fb950;
  padding: 14px 20px;
  border-radius: 10px;
  animation:
    slideIn  0.35s ease-out forwards,
    fadeOut  0.4s  ease-in  3.6s  forwards; /* Disparaît à t=3.6s */
}

@keyframes slideIn {
  from { transform: translateX(120%); opacity: 0; }
  to   { transform: translateX(0);    opacity: 1; }
}

@keyframes fadeOut {
  from { transform: translateX(0);    opacity: 1; }
  to   { transform: translateX(120%); opacity: 0; }
}


/* ════ 4. SKELETON SHIMMER ════ */
.skeleton {
  background: linear-gradient(
    90deg,
    #1f2937 25%,
    #374151 50%,
    #1f2937 75%
  );
  background-size: 200% 100%;
  border-radius: 6px;
  animation: shimmer 1.5s infinite;
}

@keyframes shimmer {
  0%   { background-position: 200% 0; }
  100% { background-position: -200% 0; }
}

.skeleton-title { height: 22px; width: 70%; margin-bottom: 12px; }
.skeleton-text  { height: 14px; width: 100%; margin-bottom: 8px; }
.skeleton-text:last-child { width: 55%; }


/* ════ ACCESSIBILITÉ — Respect des préférences ════ */
@media (prefers-reduced-motion: reduce) {
  .card-3d,
  .notification,
  .skeleton,
  .btn-load::after {
    animation: none !important;
    transition: none !important;
  }
  /* Montrer directement les états finaux */
  .notification { opacity: 1; transform: none; }
}

// ── Wrapper avec timeout ──
function fetchWithTimeout(url, timeoutMs = 5000) {
  const controller = new AbortController();
  const timeoutId  = setTimeout(() => controller.abort(), timeoutMs);

  return fetch(url, { signal: controller.signal })
    .then(res => {
      clearTimeout(timeoutId);
      if (!res.ok) throw new Error(`HTTP ${res.status} sur ${url}`);
      return res.json();
    })
    .catch(err => {
      clearTimeout(timeoutId);
      throw err.name === 'AbortError'
        ? new Error(`Timeout (${timeoutMs}ms) sur ${url}`)
        : err;
    });
}

// ── Version 1 : Promise.all — tout ou rien ──
async function fetchAllOrNothing() {
  const t0 = performance.now();
  try {
    const [users, products, orders] = await Promise.all([
      fetchWithTimeout('/api/users',    3000),
      fetchWithTimeout('/api/products', 3000),
      fetchWithTimeout('/api/orders',   3000),
    ]);
    const elapsed = (performance.now() - t0).toFixed(0);
    console.log(`✅ Toutes les données récupérées en ${elapsed}ms`);
    return { users, products, orders };
  } catch (err) {
    // Une seule erreur suffit à déclencher ce catch
    console.error(`❌ Échec global : ${err.message}`);
    throw err;
  }
}

// ── Version 2 : Promise.allSettled — résultats partiels ──
async function fetchBestEffort() {
  const t0      = performance.now();
  const endpoints = [
    { key: 'users',    url: '/api/users'    },
    { key: 'products', url: '/api/products' },
    { key: 'orders',   url: '/api/orders'   },
  ];

  const results = await Promise.allSettled(
    endpoints.map(e => fetchWithTimeout(e.url, 3000))
  );

  const elapsed = (performance.now() - t0).toFixed(0);
  const summary = { data: {}, errors: [] };

  results.forEach((result, i) => {
    const { key } = endpoints[i];
    if (result.status === 'fulfilled') {
      summary.data[key] = result.value;
      console.log(`✅ ${key} : ${result.value.length ?? 1} éléments`);
    } else {
      summary.errors.push({ key, error: result.reason.message });
      console.warn(`⚠️  ${key} indisponible : ${result.reason.message}`);
    }
  });

  console.log(`\n⏱ Temps total : ${elapsed}ms`);
  console.log(`📊 Succès : ${Object.keys(summary.data).length}/3`);
  return summary;
}

fetchBestEffort();

import { useReducer, useCallback } from 'react';

// ── Types ──
type FieldType = 'text' | 'email' | 'password' | 'select' | 'checkbox' | 'textarea';

interface ValidationRules {
  required?  : boolean;
  minLength? : number;
  maxLength? : number;
  pattern?   : RegExp;
  message?   : string; // message d'erreur custom
}

interface FieldConfig {
  name       : string;
  label      : string;
  type       : FieldType;
  placeholder?: string;
  options?   : { value: string; label: string }[]; // pour select
  validation?: ValidationRules;
}

type FormValues = Record<string, string | boolean>;
type FormErrors = Record<string, string>;

interface FormState { values: FormValues; errors: FormErrors; touched: Set<string>; }

type FormAction =
  | { type: 'SET_VALUE'; field: string; value: string | boolean }
  | { type: 'SET_ERROR'; field: string; error: string }
  | { type: 'TOUCH';     field: string };

// ── Reducer ──
function formReducer(state: FormState, action: FormAction): FormState {
  switch (action.type) {
    case 'SET_VALUE':
      return { ...state, values: { ...state.values, [action.field]: action.value } };
    case 'SET_ERROR':
      return { ...state, errors: { ...state.errors, [action.field]: action.error } };
    case 'TOUCH':
      return { ...state, touched: new Set([...state.touched, action.field]) };
    default: return state;
  }
}

// ── Moteur de validation ──
function validateField(value: string | boolean, rules?: ValidationRules): string {
  if (!rules) return '';
  const strVal = String(value);
  if (rules.required && !value) return rules.message || 'Ce champ est obligatoire';
  if (rules.minLength && strVal.length < rules.minLength)
    return rules.message || `Minimum ${rules.minLength} caractères`;
  if (rules.maxLength && strVal.length > rules.maxLength)
    return rules.message || `Maximum ${rules.maxLength} caractères`;
  if (rules.pattern && !rules.pattern.test(strVal))
    return rules.message || 'Format invalide';
  return '';
}

// ── Composants de champ ──
function TextField({ field, value, error, onChange, onBlur }: any) {
  return (
    <div className="field">
      <label>{field.label}{field.validation?.required && ' *'}</label>
      <input
        type={field.type}
        value={value as string}
        placeholder={field.placeholder}
        onChange={e => onChange(field.name, e.target.value)}
        onBlur={() => onBlur(field.name)}
        className={error ? 'invalid' : ''}
      />
      {error && <span className="error">{error}</span>}
    </div>
  );
}

function SelectField({ field, value, error, onChange, onBlur }: any) {
  return (
    <div className="field">
      <label>{field.label}</label>
      <select value={value as string} onChange={e => onChange(field.name, e.target.value)} onBlur={() => onBlur(field.name)}>
        <option value="">-- Choisir --</option>
        {field.options?.map((o: any) => <option key={o.value} value={o.value}>{o.label}</option>)}
      </select>
      {error && <span className="error">{error}</span>}
    </div>
  );
}

// ── Composant principal ──
interface DynamicFormProps {
  config   : FieldConfig[];
  onSubmit : (values: FormValues) => void;
}

export function DynamicForm({ config, onSubmit }: DynamicFormProps) {
  const initialValues = config.reduce<FormValues>((acc, f) =>
    ({ ...acc, [f.name]: f.type === 'checkbox' ? false : '' }), {});

  const [state, dispatch] = useReducer(formReducer, {
    values: initialValues, errors: {}, touched: new Set()
  });

  const handleChange = useCallback((field: string, value: string | boolean) => {
    dispatch({ type: 'SET_VALUE', field, value });
  }, []);

  const handleBlur = useCallback((field: string) => {
    dispatch({ type: 'TOUCH', field });
    const fieldConfig = config.find(f => f.name === field)!;
    const error = validateField(state.values[field], fieldConfig.validation);
    dispatch({ type: 'SET_ERROR', field, error });
  }, [config, state.values]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    let valid = true;
    config.forEach(f => {
      const error = validateField(state.values[f.name], f.validation);
      if (error) { dispatch({ type: 'SET_ERROR', field: f.name, error }); valid = false; }
    });
    if (valid) onSubmit(state.values);
  };

  return (
    <form onSubmit={handleSubmit}>
      {config.map(field => {
        const props = { field, value: state.values[field.name], error: state.errors[field.name], onChange: handleChange, onBlur: handleBlur };
        if (field.type === 'select')   return <SelectField key={field.name} {...props} />;
        return <TextField key={field.name} {...props} />;
      })}
      <button type="submit">Soumettre</button>
    </form>
  );
}
